import{z as B,x as I,o as s,c as n,q as i,j as t,D as A,d as e,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"MSI / MSI-X 中断","description":"","frontmatter":{"title":"MSI / MSI-X 中断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/msi-msix.md","filePath":"cs/msi-msix.md","lastUpdated":1791413859000}'),C={name:"cs/msi-msix.md"};function p(d,E,S,M,D,m){const r=I("Mermaid");return s(),n("div",null,[E[2]||(E[2]=i('<h1 id="msi-msi-x-中断" tabindex="-1">MSI / MSI-X 中断 <a class="header-anchor" href="#msi-msi-x-中断" aria-label="Permalink to &quot;MSI / MSI-X 中断&quot;">​</a></h1><div class="epigraph"><p>设备不再拉一根 INTx 线，而是写一个约定的内存地址：这条 Memory Write TLP 被主机构成中断，向量在消息数据里。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Intel 64 and IA-32 Architectures Software Developer’s Manual 整理</footer></div><p><a href="/cs/pcie-tlp-bar">上一课</a>让设备能发 Memory Write。组成/OS 课的 <a href="/cs/plic-irq">PLIC</a> 是线汇聚模型。缺口是 PCI <strong>消息信号中断</strong>：MSI 与 MSI-X 用写事务代替边沿/电平线，向量可以很多。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 INTx 共享、电平、桥上虚拟线，扩展性差。MSI：配置能力里写 Message Address/Data，设备发一条写。MSI-X：独立表（常在 BAR）每向量各地址/数据，可掩码，向量数远大于 MSI。缺口不是 TLP 头格式重讲，而是：<strong>中断=定向写</strong>，与 DMA 写同类，只是地址落在中断控制器接收窗口（如 x86 的 FEE0_xxxx 或 IOMMU/APIC 区域）。</p><p>RISC-V 平台可用 MSI 接到 IMSIC 或经转换接到 PLIC，细节因平台而异，本课钉 PCI 侧合同。</p><h3 id="msi-不是「更快的轮询」" tabindex="-1">MSI 不是「更快的轮询」 <a class="header-anchor" href="#msi-不是「更快的轮询」" aria-label="Permalink to &quot;MSI 不是「更快的轮询」&quot;">​</a></h3><p>没有消息时 CPU 不因该设备进中断；轮询是软件读门铃。把 MSI-X 理解成硬件自动 poll BAR，中断亲和与节能模型全错。过多向量浪费表项；过少则共享处理函数。</p><p><span class="marginnote">MSI 就像把「按门铃」换成「往指定信箱投一张写着编号的纸条」：门铃只有响与不响，多户人家还得开门猜是谁；纸条自带身份，主机一看编号就知道是哪个设备、哪个事件，不用共享、不用轮询猜人。</span></p><p><span class="marginnote">PCI-SIG 定义 MSI/MSI-X 能力结构。Intel SDM 描述本地 APIC 如何接收这些写。下一课 APIC 路由。Linux 驱动写 <code>pci_alloc_irq_vectors</code> 一类，本课不背 API。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>枚举时 OS 分配向量，编程 MSI-X 表，使能。设备事件：写对应表项的地址/数据。主机：APIC 投递到目标 CPU，软件在处理函数里读设备原因寄存器（仍经 BAR）。与 DMA 写序：描述符写完再发 MSI，通常靠 PCIe 的同路径 Posted 序或显式围栏——后课 DMA 再钉。</p>',12)),(s(),t(o,null,{default:A(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E8%AE%BE%E5%A4%87%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20WR%5B%22Memory%20Write%20%E5%88%B0%20MSI%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20WR%20--%3E%20APIC%5B%22%E4%B8%BB%E6%9C%BA%E4%B8%AD%E6%96%AD%E6%8E%A7%E5%88%B6%E5%99%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20APIC%20--%3E%20CPU%5B%22%E7%9B%AE%E6%A0%87%20CPU%20%E5%90%91%E9%87%8F%22%5D%0A%20%20CPU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AAPIC%20%E5%A6%82%E4%BD%95%E9%80%89%E6%A0%B8%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"错误消息（AER）也走 Message TLP，不是 MSI 表，点名区分。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("下一课 APIC/IOAPIC/x2APIC 决定向量落到哪颗核，与 "),a("a",{href:"/cs/irq-affinity"},"irq affinity"),e(" 软件策略衔接。本课只把 PCI 设备从「拉线」换成「写消息」。")],-1)),E[6]||(E[6]=a("p",null,"给个量级：INTx 一共只有 4 条传统线，多个设备共享一条就得靠软件逐一排查是谁；MSI 一个设备最多 32 个向量，MSI-X 表可到 2048 项——一张多队列网卡给每个收包队列单独配一个中断，都绰绰有余。这是「向量可以很多」的具体含义。",-1)),(s(),t(o,null,{default:A(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TBL%5B%22MSI-X%20%E8%A1%A8%EF%BC%88%E5%9C%A8%20BAR%20%E5%86%85%EF%BC%8COS%20%E5%B7%B2%E7%BC%96%E7%A8%8B%EF%BC%89%22%5D%20--%3E%20E0%5B%22%E8%A1%A8%E9%A1%B9%200%EF%BC%9A%E5%9C%B0%E5%9D%80%20A0%20%2F%20%E6%95%B0%E6%8D%AE%20D0%22%5D%0A%20%20TBL%20--%3E%20E1%5B%22%E8%A1%A8%E9%A1%B9%201%EF%BC%9A%E5%9C%B0%E5%9D%80%20A1%20%2F%20%E6%95%B0%E6%8D%AE%20D1%22%5D%0A%20%20TBL%20--%3E%20E2%5B%22%E8%A1%A8%E9%A1%B9%202%EF%BC%9A%E5%9C%B0%E5%9D%80%20A2%20%2F%20%E6%95%B0%E6%8D%AE%20D2%EF%BC%8C%E5%B7%B2%E6%8E%A9%E7%A0%81%22%5D%0A%20%20RXQ%5B%22%E7%BD%91%E5%8D%A1%E6%94%B6%E5%8C%85%E9%98%9F%E5%88%97%200%20%E5%AE%8C%E6%88%90%22%5D%20--%3E%7C%22%E5%86%99%20A0%20%E9%85%8D%20D0%22%7C%20E0%0A%20%20TXQ%5B%22%E5%8F%91%E9%80%81%E9%98%9F%E5%88%97%E7%A9%BA%22%5D%20--%3E%7C%22%E5%86%99%20A1%20%E9%85%8D%20D1%22%7C%20E1%0A%20%20E0%20--%3E%20C0%5B%22%E6%8A%95%E9%80%92%E5%88%B0%E6%A0%B8%200%20%E7%9A%84%E5%90%91%E9%87%8F%22%5D%0A%20%20E1%20--%3E%20C1%5B%22%E6%8A%95%E9%80%92%E5%88%B0%E6%A0%B8%201%20%E7%9A%84%E5%90%91%E9%87%8F%22%5D%0A%20%20E2%20-.-%3E%7C%22%E8%A2%AB%E6%8E%A9%E7%A0%81%EF%BC%9A%E4%B8%8D%E5%8F%91%E6%B6%88%E6%81%AF%22%7C%20NONE%5B%22%E4%B8%8D%E4%BA%A7%E7%94%9F%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<p>初学者容易以为 MSI 是设备「抢总线插嘴喊一嗓子」的特殊操作——实际上它就是一次普通的 Memory Write TLP，照常排队、照常受流控；主机唯一 special 的地方，是「写的地址落在中断接收窗口」这一条被认成中断，其余与 DMA 写别无二致。</p><p><span class="marginnote">常见误区：把 MSI-X 的 2048 项当成「性能上限」——上限意义在「每个队列独立中断、免共享一条线的锁」，队列用不满 32 项的设备选 MSI 已足够；为用满表项而人为拆分队列纯属浪费。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 IOMMU 中断重映射表的全部字段，不把虚拟 MSI 注入写成完整 VFIO 课。不讨论中断风暴的全部缓解。</p><p>后课默认：PCIe 设备用 MSI/MSI-X 写消息投递中断；向量在表里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>INTx 共享线被 MSI 写事务替代。</li><li>MSI-X 每向量独立地址/数据，表在 BAR。</li><li>投递窗口由主机中断控制器定义。</li><li>出处：PCI-SIG PCIe Base Spec；Intel SDM。</li></ul>',7))])}const f=B(C,[["render",p]]);export{c as __pageData,f as default};
